import TextCM from '../../components/Text';
import HeaderCM from '../../components/Header/HeaderCM';

const renderTabBar = (
  props: SceneRendererProps & {
    navigationState: NavigationState<{
      key: string;
      title: string;
    }>;
  },
) => (
  <TabBar
    {...props}
    indicatorStyle={styles.indicatorStyle}
    indicatorContainerStyle={styles.indicatorContainerStyle}
    style={styles.tabBarStyle}
    tabStyle={styles.tabStyle}
    activeColor="#0673C6"
    inactiveColor="#667085"
    contentContainerStyle={styles.contentContainerStyle}
    // renderLabel={({route, focused, color}) => (
    //   <View
    //     style={{
    //       flex: 1,
    //       alignItems: 'center',
    //       justifyContent: 'center',
    //     }}>
    //     <TextCM style={(styles.txtTabText, {color})}>{route.title}</TextCM>
    //   </View>
    // )}
  />
);

const TitleSign = (label: string) => {
  const {t} = useTranslation();
  return (
    <TextCM style={styles.textTitle}>
      {label}
      <TextCM style={styles.dotRequired}>*</TextCM>
      {'  '}
      <TextCM style={styles.textDescription}>{t('eContract.AC.fileDescriptions')}</TextCM>
    </TextCM>
  );
};

const InfoSignature = () => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();
  const [index, setIndex] = useState(0);

  const [routes] = useState([
    {key: 'imageSignature', title: t('eContract.AC.imageSign')},
    {key: 'digitalSignature', title: t('eContract.AC.digitalImageSign')},
  ]);

  const renderScene = useMemo(
    () =>
      SceneMap({
        imageSignature: () => <ImageSignature />,
        digitalSignature: () => <DigitalSignature />,
      }),
    [],
  );

  return (
    <>
      <HeaderCM title={t('eContract.AC.titleSign')} />
      <View style={{flex: 1}}>
        <TabView
          renderTabBar={renderTabBar}
          navigationState={{index, routes}}
          renderScene={renderScene}
          onIndexChange={setIndex}
        />
      </View>
      {/* <View style={styles.ctnSignature}>
        {TitleSign(t('eContract.AC.imageSign'))}
        <ImageSignature />
        {TitleSign(t('eContract.AC.digitalSign'))}
        <DigitalSignature />

        <ButtonCM
          label={t('eContract.CM.BtnConfirm')}
          onPress={() => navigation.goBack()}
          style={{marginTop: SizeDP(16)}}
        />
      </View> */}
    </>
  );
};

export default InfoSignature;
