import {
  View,
  Text,
  Platform,
  TouchableWithoutFeedback,
  Keyboard,
} from 'react-native';
import React, {useEffect, useRef, useState} from 'react';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import PicFontView from '../PicFontView';
import {AutoSizeText, ResizeTextMode} from 'react-native-auto-size-text';
import {isEmpty} from 'lodash';
import ViewShot from 'react-native-view-shot';
import {captureRef} from 'react-native-view-shot';
import TextFieldCM from '../../../../../../../../../components/TextField';
import TextCM from '../../../../../../../../../components/Text';
import {FontSize} from '../../../../../../../../../constants';
import ButtonCM from '../../../../../../../../../components/Button';
import useStoreNoti from '../../../../../../../store/store';

type Props = {
  onContinue: (value: string) => void;
};
const result = Platform.OS === 'android' ? 'zip-base64' : 'base64';

const InputDigital = ({onContinue}: Props) => {
  const ref = useRef<any>();

  const currentSignDozen = useStoreNoti(state => state.currentSignDozens);

  const {t} = useTranslation();

  const [fullName, setFullName] = useState('');
  const [fontFamily, setFontFamily] = useState<any>();

  useEffect(() => {
    if (!fullName.trim()) {
      setFontFamily(null);
    }
  }, [fullName]);

  const getFirstId = () => {
    const ids = currentSignDozen?.map(item => item.id);
    return ids?.[0];
  };

  const onPressContinue = () => {
    if (ref.current) {
      captureRef(ref, {
        quality: 0.8,
        result,
        width: 326,
        height: 164,
      }).then((base64: string) => {
        onContinue(base64);
      });
    }
  };

  return (
    <TouchableWithoutFeedback onPress={() => Keyboard.dismiss()}>
      <View style={styles.container}>
        <View style={styles.body}>
          <TextFieldCM
            label={t('eContract.AI.TxtFullName')}
            isRequired
            value={fullName}
            onChangeText={setFullName}
          />
          <PicFontView
            onPicStatus={setFontFamily}
            value={fontFamily}
            fullName={fullName.trim()}
          />
          <View style={styles.viewResult}>
            <TextCM style={styles.txtResult}>{t('eContract.NT.TxtResult')}</TextCM>
            <ViewShot
              ref={ref}
              options={{format: 'jpg', quality: 0.9}}
              style={{flex: 1}}>
              {fullName.trim() ? (
                <View style={styles.viewImageResult}>
                  <TextCM style={styles.txtDes}>
                    {t('eContract.NT.TxtEContractSignedBy')}
                  </TextCM>
                  <AutoSizeText
                    fontSize={FontSize.FontGreatest}
                    numberOfLines={1}
                    style={[
                      styles.txtName,
                      fontFamily && {
                        fontFamily: fontFamily.id as string,
                      },
                    ]}
                    mode={ResizeTextMode.max_lines}>
                    {fullName}
                  </AutoSizeText>
                  <TextCM style={styles.txtDes1}>{getFirstId()}</TextCM>
                </View>
              ) : (
                <View style={styles.viewNoname} />
              )}
            </ViewShot>
          </View>
        </View>
        <ButtonCM
          label={t('eContract.CM.BtnContinue')}
          onPress={onPressContinue}
          disabled={isEmpty(fullName.trim())}
        />
      </View>
    </TouchableWithoutFeedback>
  );
};

export default InputDigital;
