import {yupResolver} from '@hookform/resolvers/yup';
import React, {useEffect} from 'react';
import {FormProvider, useForm} from 'react-hook-form';
import {useTranslation} from 'react-i18next';
import {
  KeyboardAvoidingView,
  Modal,
  TouchableOpacity,
  View,
} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import * as yup from 'yup';
import styles from './styles';
import YupTextField from '../ModalCancelDocument/components/YupTextField';
import {IDocument} from '../../../../../model/interface/envelope.interface';
import {IcBlackLeftArrow} from '../../../../../assets/images';
import TextCM from '../../../../../components/Text';
import ButtonCM from '../../../../../components/Button';
import Toast from 'react-native-toast-message';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';

type ModalCreateTemplate = {
  onClose: () => void;
  isVisible: boolean;
  data: IDocument;
};

const ModalCreateTemplate = ({
  onClose,
  isVisible,
  data,
}: ModalCreateTemplate) => {
  const {t} = useTranslation();
  const schema = yup.object().shape({
    content: yup.string().trim().required(t('eContract.SU.fieldRequired')),
  });
  const insets = useSafeAreaInsets();
  const DocumentServices = useDocumentServices();
  useEffect(() => {
    if (isVisible) {
      methods.reset({
        content: '',
      });
    }
  }, [isVisible]);

  const methods = useForm({
    mode: 'onBlur',
    resolver: yupResolver(schema),
    defaultValues: {
      content: '',
    },
  });

  const onSubmit = async () => {
    const body = {
      aliasName: null,
      content: methods.getValues().content.trim(),
      createdBy: null,
      createdDate: null,
      custId: data.custId,
      format: 'text',
      id: null,
      lastModifiedBy: null,
      lastModifiedDate: null,
      orgIn: data.orgIn,
      owner: data.owner,
      priority: 0,
    };
    try {
      const res = await DocumentServices.saveTemplate(body);
      Toast.show({
        type: 'success',
        text1: t('eContract.DC.Messages.TxtCreateTemplateMessageSuccess'),
      });
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('eContract.CM.TxtSystemError'),
      });
    } finally {
      onClose();
    }
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <KeyboardAvoidingView
        style={{flex: 1}}
        behavior={'padding'}
        keyboardVerticalOffset={-insets.bottom}>
        <View style={styles.ctnContainer}>
          <View style={styles.ctnTop} onTouchEnd={onClose} />
          <View style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
            <View style={styles.viewHeader}>
              <TouchableOpacity onPress={onClose}>
                <IcBlackLeftArrow width={14} height={16} />
              </TouchableOpacity>
              <TextCM style={styles.txtTitle}>
                {t('eContract.DC.CancelDocument.TxtCreateTemplateMessage')}
              </TextCM>
              <View />
            </View>
            <View style={styles.viewBody}>
              <FormProvider {...methods}>
                <YupTextField
                  controlName={'content'}
                  label={t('eContract.DC.CancelDocument.TxtContent')}
                  maxLength={100}
                />
                <ButtonCM
                  disabled={!methods.formState.isValid}
                  label={t('eContract.CM.TxtSave')}
                  onPress={onSubmit}
                />
              </FormProvider>
            </View>
          </View>
        </View>
      </KeyboardAvoidingView>
    </Modal>
  );
};

export default ModalCreateTemplate;
