import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {Modal, TouchableOpacity, useWindowDimensions, View} from 'react-native';
import DatePicker from 'react-native-date-picker';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import styles from './styles';
import TextCM from '../Text';
import {IconBlackLeftArrow} from '../../assets/images';
import {useAppSelector} from '../../hook/useRedux';
import ButtonCM from '../Button';

type ModalPicDateProp = {
  title: string;
  onClose: () => void;
  isVisible: boolean;
  onSave?: (date: Date) => void;
  initDate?: Date;
  labelSave?: string;
  minDate?: Date;
  maxDate?: Date;
};

const ModalPicDate = ({
  title,
  onClose,
  isVisible,
  onSave,
  initDate,
  labelSave,
  minDate,
  maxDate,
}: ModalPicDateProp) => {
  const {t} = useTranslation();

  const [date, setDate] = useState(initDate || new Date());
  const insets = useSafeAreaInsets();
  const language = useAppSelector(state => state.common.language);
  const onDateChange = (data: Date) => {
    setDate(data);
  };

  const {width} = useWindowDimensions();

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <View style={styles.ctnContainer}>
        <View style={styles.ctnTop} onTouchEnd={onClose} />
        <View style={[styles.ctnContent, {paddingBottom: 16 + insets.bottom}]}>
          <View style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IconBlackLeftArrow width={14} height={16} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>{title}</TextCM>
            <View />
          </View>
          <View style={styles.viewDate}>
            <DatePicker
              date={date}
              onDateChange={onDateChange}
              mode="date"
              locale={language}
              style={{
                width: width - 36,
              }}
              theme="light"
              maximumDate={maxDate ? maxDate : undefined}
              minimumDate={minDate ? minDate : undefined}
            />
          </View>
          <ButtonCM
            label={labelSave || t('eContract.CM.TxtSave')}
            onPress={() => {
              onSave?.(date);
              onClose();
            }}
          />
        </View>
      </View>
    </Modal>
  );
};

export default ModalPicDate;
