export enum RecipientRole {
  REQUESTER = 'requester',
  SIGNER = 'signer',
  COORDINATOR = 'coordinator',
  REVIEWER = 'reviewer',
  STAMPER = 'stamper',
  CC = 'cc',
  FIRST_CERTIFIED = 'cecaSeal',
  LAST_CERTIFIED = 'cecaStamp',
}

export enum RecipientInfoStatus {
  PROCESSING = 'processing',
  PROCESSING_1 = 'processing_1', // Dang thuc hien theo lo
  REJECTED = 'rejected',
  OVERDUE = 'overdue',
  WAITING = 'waiting',
  ACCEPTED = 'accepted',
  CC = 'cced',
}

export enum DocumentStatus {
  DRAFT = 'draft',
  PROCESSING = 'processing',
  REJECTED = 'rejected',
  OVERDUE = 'overdue',
  VOIDED = 'voided',
  COMPLETED = 'completed',
}
export enum HistoryStatus {
  /** Đã ký */
  SIGNED = 'signed',
  /** Đã xem */
  REVIEWED = 'reviewed',
  /** Đã đóng dấu */
  STAMPED = 'stamped',
  /** Đã điều phối */
  COORDINATED = 'coordinated',
  /** Đã CC */
  CCED = 'cced',
  /** Từ chối ký */
  REJECTED_SIGNING = 'rejected-signing',
  /** Từ chối đóng dấu */
  REJECTED_STAMPING = 'rejected-stamping',
  /** Từ chối điều phối */
  REJECTED_COORDINATING = 'rejected-coordinating',
  /** Từ chối xem xét */
  REJECTED_REVIEWING = 'rejected-reviewing',
  /** Từ chối CC */
  REJECTED_CC = 'rejected-cc',
  /** Đang ký */
  SIGNING = 'signing',
  /** Đang đóng dấu */
  STAMPING = 'stamping',
  /** Đang xem xét */
  REVIEWING = 'reviewing',
  /** Đang điều phối */
  COORDINATING = 'coordinating',
  /** Đang CC */
  CCING = 'cc-ing',
  /** Chờ ký */
  WAIT_FOR_SIGNING = 'wait-for-signing',
  /** Chờ đóng dấu */
  WAIT_FOR_STAMPING = 'wait-for-stamping',
  /** Chờ xem xét */
  WAIT_FOR_REVIEWING = 'wait-for-reviewing',
  /** Chờ điều phối */
  WAIT_FOR_COORDINATING = 'wait-for-coordinating',
  /** Chờ CC */
  WAIT_FOR_CC = 'wait-for-cc',
}

export const convertHistoryStatus = (status: string, role: string) => {
  switch (status) {
    case RecipientInfoStatus.ACCEPTED:
      return statusConvertFinished(role, status);
    case RecipientInfoStatus.PROCESSING:
      return statusConvertProcessing(role);
    case '':
      return statusConvertWaiting(role);
    case null:
      return statusConvertWaiting(role);
    case RecipientInfoStatus.CC:
      return statusConvertFinished(role, status);
    default:
      return statusConvertFinished(role, status);
  }
};

const statusConvertFinished = (role: string, status: string) => {
  if (
    role === RecipientRole.COORDINATOR &&
    status === RecipientInfoStatus.ACCEPTED
  ) {
    return HistoryStatus.COORDINATED;
  }
  if (
    role === RecipientRole.COORDINATOR &&
    status === RecipientInfoStatus.REJECTED
  ) {
    return HistoryStatus.REJECTED_COORDINATING;
  }
  if (
    (role === RecipientRole.SIGNER ||
      role === RecipientRole.FIRST_CERTIFIED ||
      role === RecipientRole.LAST_CERTIFIED) &&
    status === RecipientInfoStatus.ACCEPTED
  ) {
    return HistoryStatus.SIGNED;
  }
  if (
    (role === RecipientRole.SIGNER ||
      role === RecipientRole.FIRST_CERTIFIED ||
      role === RecipientRole.LAST_CERTIFIED) &&
    status === RecipientInfoStatus.REJECTED
  ) {
    return HistoryStatus.REJECTED_SIGNING;
  }
  if (
    role === RecipientRole.STAMPER &&
    status === RecipientInfoStatus.ACCEPTED
  ) {
    return HistoryStatus.STAMPED;
  }
  if (
    role === RecipientRole.STAMPER &&
    status === RecipientInfoStatus.REJECTED
  ) {
    return HistoryStatus.REJECTED_STAMPING;
  }
  if (
    role === RecipientRole.REVIEWER &&
    status === RecipientInfoStatus.ACCEPTED
  ) {
    return HistoryStatus.REVIEWED;
  }
  if (
    role === RecipientRole.REVIEWER &&
    status === RecipientInfoStatus.REJECTED
  ) {
    return HistoryStatus.REJECTED_REVIEWING;
  }
  if (role === RecipientRole.CC && status === RecipientInfoStatus.CC) {
    return HistoryStatus.CCED;
  }
  if (role === RecipientRole.CC && status === RecipientInfoStatus.REJECTED) {
    return HistoryStatus.REJECTED_CC;
  }
  return '';
};

const statusConvertProcessing = (role: string) => {
  if (
    role === RecipientRole.SIGNER ||
    role === RecipientRole.FIRST_CERTIFIED ||
    role === RecipientRole.LAST_CERTIFIED
  ) {
    return HistoryStatus.SIGNING;
  }
  if (role === RecipientRole.STAMPER) {
    return HistoryStatus.STAMPING;
  }
  if (role === RecipientRole.REVIEWER) {
    return HistoryStatus.REVIEWING;
  }
  if (role === RecipientRole.COORDINATOR) {
    return HistoryStatus.COORDINATING;
  }

  if (role === RecipientRole.CC) {
    return HistoryStatus.CCING;
  }
  return '';
};

const statusConvertWaiting = (role: string) => {
  if (
    role === RecipientRole.SIGNER ||
    role === RecipientRole.FIRST_CERTIFIED ||
    role === RecipientRole.LAST_CERTIFIED
  ) {
    return HistoryStatus.WAIT_FOR_SIGNING;
  }
  if (role === RecipientRole.STAMPER) {
    return HistoryStatus.WAIT_FOR_STAMPING;
  }
  if (role === RecipientRole.REVIEWER) {
    return HistoryStatus.WAIT_FOR_REVIEWING;
  }
  if (role === RecipientRole.COORDINATOR) {
    return HistoryStatus.WAIT_FOR_COORDINATING;
  }
  if (role === RecipientRole.CC) {
    return HistoryStatus.WAIT_FOR_CC;
  }
  return '';
};

export const mappingRecipientToText = (value: string) => {
  switch (value) {
    case HistoryStatus.REVIEWING:
      return 'eContract.DC.HistoryStatus.reviewing';
    case HistoryStatus.SIGNED:
      return 'eContract.DC.HistoryStatus.signed';
    case HistoryStatus.STAMPED:
      return 'eContract.DC.HistoryStatus.stamped';
    case HistoryStatus.COORDINATED:
      return 'eContract.DC.HistoryStatus.coordinated';
    case HistoryStatus.CCED:
      return 'eContract.DC.HistoryStatus.cced';
    case HistoryStatus.REJECTED_SIGNING:
      return 'eContract.DC.HistoryStatus.rejectedSigning';
    case HistoryStatus.REJECTED_STAMPING:
      return 'eContract.DC.HistoryStatus.rejectedStamping';
    case HistoryStatus.REJECTED_COORDINATING:
      return 'eContract.DC.HistoryStatus.rejectedCoordinating';
    case HistoryStatus.REJECTED_REVIEWING:
      return 'eContract.DC.HistoryStatus.rejectedReviewing';
    case HistoryStatus.REJECTED_CC:
      return 'eContract.DC.HistoryStatus.rejectedCC';
    case HistoryStatus.SIGNING:
      return 'eContract.DC.HistoryStatus.signing';
    case HistoryStatus.STAMPING:
      return 'eContract.DC.HistoryStatus.stamping';
    case HistoryStatus.WAIT_FOR_SIGNING:
      return 'eContract.DC.HistoryStatus.waitForSigning';
    case HistoryStatus.WAIT_FOR_STAMPING:
      return 'eContract.DC.HistoryStatus.waitForStamping';
    case HistoryStatus.WAIT_FOR_REVIEWING:
      return 'eContract.DC.HistoryStatus.waitForReviewing';
    case HistoryStatus.WAIT_FOR_COORDINATING:
      return 'eContract.DC.HistoryStatus.waitForCoordinating';
    case HistoryStatus.WAIT_FOR_CC:
      return 'eContract.DC.HistoryStatus.waitForCC';
    case HistoryStatus.CCING:
      return 'eContract.DC.HistoryStatus.ccing';
    case HistoryStatus.REVIEWED:
      return 'eContract.DC.HistoryStatus.reviewed';
    case HistoryStatus.COORDINATING:
      return 'eContract.DC.HistoryStatus.coordinating';
    default:
      return 'error status';
  }
};

export const mappingDocumentStatusToText = (value: string) => {
  switch (value) {
    case DocumentStatus.COMPLETED:
      return 'eContract.DC.DocumentStatus.completed';
    case DocumentStatus.OVERDUE:
      return 'eContract.DC.DocumentStatus.overdue';
    case DocumentStatus.PROCESSING:
      return 'eContract.DC.DocumentStatus.processing';
    case DocumentStatus.REJECTED:
      return 'eContract.DC.DocumentStatus.rejected';
    case DocumentStatus.VOIDED:
      return 'eContract.DC.DocumentStatus.voided';
    default:
      return 'error document status';
  }
};

export const mappingColorDocumentStatus = (value: string) => {
  switch (value) {
    case DocumentStatus.COMPLETED:
      return '#219342';
    case DocumentStatus.OVERDUE:
      return '#DA3E33';
    case DocumentStatus.PROCESSING:
      return '#0673C6';
    case DocumentStatus.REJECTED:
      return '#DA3E33';
    case DocumentStatus.VOIDED:
      return '#DA3E33';
    default:
      return '#DA3E33';
  }
};

export const mappingColorHistoryStatus = (value: string) => {
  switch (value) {
    case HistoryStatus.SIGNED:
    case HistoryStatus.REVIEWED:
    case HistoryStatus.STAMPED:
    case HistoryStatus.COORDINATED:
    case HistoryStatus.CCED:
      return '#219342';
    case HistoryStatus.WAIT_FOR_COORDINATING:
    case HistoryStatus.WAIT_FOR_REVIEWING:
    case HistoryStatus.WAIT_FOR_SIGNING:
    case HistoryStatus.WAIT_FOR_STAMPING:
    case HistoryStatus.WAIT_FOR_CC:
      return '#E18308';
    case HistoryStatus.REJECTED_COORDINATING:
    case HistoryStatus.REJECTED_CC:
    case HistoryStatus.REJECTED_REVIEWING:
    case HistoryStatus.REJECTED_SIGNING:
    case HistoryStatus.REJECTED_STAMPING:
      return '#DA3E33';
    default:
      return '#0673C6';
  }
};

export const mappingBGColorHistoryStatus = (value: string) => {
  switch (value) {
    case HistoryStatus.SIGNED:
    case HistoryStatus.REVIEWED:
    case HistoryStatus.STAMPED:
    case HistoryStatus.COORDINATED:
    case HistoryStatus.CCED:
      return '#E9F6ED';
    case HistoryStatus.WAIT_FOR_COORDINATING:
    case HistoryStatus.WAIT_FOR_REVIEWING:
    case HistoryStatus.WAIT_FOR_SIGNING:
    case HistoryStatus.WAIT_FOR_STAMPING:
    case HistoryStatus.WAIT_FOR_CC:
      return '#FEF4E6';
    case HistoryStatus.REJECTED_COORDINATING:
    case HistoryStatus.REJECTED_CC:
    case HistoryStatus.REJECTED_REVIEWING:
    case HistoryStatus.REJECTED_SIGNING:
    case HistoryStatus.REJECTED_STAMPING:
      return '#FEECEB';
    default:
      return '#E6F2FB';
  }
};
