import {isEmpty} from 'lodash';
import {useTranslation} from 'react-i18next';
import {Modal, ScrollView, TouchableOpacity, View} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import {getPermissionLabelById} from '../../../shareScreen/helper';
import styles from './styles';
import {useDocumentStore} from '../../../../../../../navigation/SideMenu/store/app-store';
import TextCM from '../../../../../../../components/Text';
import {DateUtils} from '../../../../../../../utils';
import {IcBlackLeftArrow} from '../../../../../../../assets/images';
import {ItemType} from '../../../../../../../navigation/SideMenu/components/CustomDrawerContent/helper';
import ButtonCM from '../../../../../../../components/Button';

type ModaShowHistoryProp = {
  onClose: () => void;
  isVisible: boolean;
  type: 'share' | 'permission';
  data: any;
};

const ModaShowHistory = ({
  onClose,
  isVisible,
  type,
  data,
}: ModaShowHistoryProp) => {
  const {t} = useTranslation();
  const currentFocused = useDocumentStore(state => state.currentFocused);
  const insets = useSafeAreaInsets();

  const renderPermision = () => {
    return (
      <View style={styles.ctnGroupCard}>
        {!isEmpty(data?.cdc?.add) && (
          <View style={styles.ctnCard}>
            <TextCM>{t('eContract.DC.ShareDocument.listPeopleAdded')}</TextCM>
            {data?.cdc?.add.map((item: any, index: number) => (
              <View key={index}>
                <TextCM style={styles.txtValue}>{`(${item.personal})`}</TextCM>
              </View>
            ))}
          </View>
        )}
        {!isEmpty(data?.cdc?.delete) && (
          <View style={styles.ctnCard}>
            <TextCM>{t('eContract.DC.ShareDocument.listPeopleDeleted')}</TextCM>
            {data?.cdc?.delete.map((item: any, index: number) => (
              <View key={index}>
                <TextCM style={styles.txtValue}>{`(${item.personal})`}</TextCM>
              </View>
            ))}
          </View>
        )}
      </View>
    );
  };

  const renderShared = () => {
    return (
      <View style={styles.ctnGroupCard}>
        {!isEmpty(data?.cdc?.previousValue) && (
          <View>
            <TextCM style={styles.label}>{t('eContract.DC.TxtOldInfo')}</TextCM>
            {data?.cdc?.previousValue.map((item: any, index: number) => (
              <View style={styles.ctnCard} key={index}>
                <TextCM style={styles.txtSmall600}>{`${item.personal}`}</TextCM>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txtValue}>
                    {t('eContract.DC.ShareDocument.allowPermission')}
                  </TextCM>
                  <TextCM style={styles.txtSmall600}>
                    {getPermissionLabelById(item?.perm)}
                  </TextCM>
                </View>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txtValue}>
                    {t('eContract.DC.ShareDocument.effectFrom')}
                  </TextCM>
                  <TextCM style={styles.txtSmall600}>
                    {DateUtils.convertIsoDateToYYYYMMDD(
                      item?.fromDate.slice(0, 10),
                    )}
                  </TextCM>
                </View>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txtValue}>
                    {t('eContract.DC.ShareDocument.effectTo')}
                  </TextCM>
                  <TextCM style={styles.txtSmall600}>
                    {DateUtils.convertIsoDateToYYYYMMDD(
                      item?.toDate.slice(0, 10),
                    )}
                  </TextCM>
                </View>
              </View>
            ))}
          </View>
        )}
        {!isEmpty(data?.cdc?.value) && (
          <View>
            {!isEmpty(data?.cdc?.previousValue) && (
              <TextCM style={styles.label}>{t('eContract.DC.TxtNewInfo')}</TextCM>
            )}
            {data?.cdc?.value.map((item: any, index: number) => (
              <View style={styles.ctnCard} key={index}>
                <TextCM style={styles.txtSmall600}>{`${item.personal}`}</TextCM>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txtValue}>
                    {t('eContract.DC.ShareDocument.allowPermission')}
                  </TextCM>
                  <TextCM style={styles.txtSmall600}>
                    {getPermissionLabelById(item?.perm)}
                  </TextCM>
                </View>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txtValue}>
                    {t('eContract.DC.ShareDocument.effectFrom')}
                  </TextCM>
                  <TextCM style={styles.txtSmall600}>
                    {DateUtils.convertIsoDateToYYYYMMDD(
                      item?.fromDate.slice(0, 10),
                    )}
                  </TextCM>
                </View>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txtValue}>
                    {t('eContract.DC.ShareDocument.effectTo')}
                  </TextCM>
                  <TextCM style={styles.txtSmall600}>
                    {DateUtils.convertIsoDateToYYYYMMDD(
                      item?.toDate.slice(0, 10),
                    )}
                  </TextCM>
                </View>
              </View>
            ))}
          </View>
        )}
      </View>
    );
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <View style={styles.ctnContainer}>
        <View style={styles.ctnTop} onTouchEnd={onClose} />
        <View style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
          <View style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={14} height={16} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>
              {type === 'share' ||
              currentFocused === ItemType.MyDocumentTemplate
                ? t('eContract.DC.ShareDocument.listDetailShared')
                : t('eContract.DC.ShareDocument.listDetailPermission')}
            </TextCM>
            <View />
          </View>
          <ScrollView style={styles.viewBody}>
            {type === 'share' ? renderShared() : renderPermision()}
          </ScrollView>
          <View style={styles.ctnButton}>
            <ButtonCM label={t('eContract.CM.BtnClose')} onPress={onClose} />
          </View>
        </View>
      </View>
    </Modal>
  );
};

export default ModaShowHistory;
