import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {
  Dimensions,
  FlatList,
  Modal,
  ScrollView,
  TouchableOpacity,
} from 'react-native';
import styles from './styles';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import TextCM from '../../../../../components/Text';
import {View as ViewCM} from 'react-native';
import {
  IcBlackLeftArrow,
  IcCheckbox,
  IcCheckboxSelect,
  IconDropdownUtility,
} from '../../../../../assets/images';
import {SizeDP} from '../../../../../constants/Size';
import ButtonCM from '../../../../../components/Button';

type ModalConfigurationProp = {
  data: any;
  onClose: () => void;
  isVisible: boolean;
  onSubmit: (item: any) => void;
};

const ModalConfigurationEmail = ({
  data,
  onClose,
  isVisible,
  onSubmit,
}: ModalConfigurationProp) => {
  const dataSubmit = data ? data : null;
  const newData = data ? data.attrs : null;
  const [dataCustom, setData] = useState<any>();
  const {t} = useTranslation();
  const insets = useSafeAreaInsets();
  const [currentDropdown, setCurrentDropdown] = useState<any>([]);
  const [mainCurrent, setMainCurrent] = useState<any>([]);

  useEffect(() => {
    if (data) {
      const sortedData = Object.values(newData).sort(
        (a: any, b: any) => a.order - b.order,
      );
      const newCheckedIds = sortedData
        .filter((item: any) => item.value)
        .map((item: any) => item.order);
      setMainCurrent(newCheckedIds);

      const recipientStartChildren = sortedData.filter((item: any) =>
        [3, 4, 5, 5.5].includes(item.order),
      );
      newData.recipient_start.children = recipientStartChildren;

      const flowFinishChildren = sortedData.filter((item: any) =>
        [10, 11, 12, 13].includes(item.order),
      );
      newData.flow_finish.children = flowFinishChildren;

      const updatedSortedData = sortedData.filter(
        (item: any) => ![3, 4, 5, 5.5, 10, 11, 12, 13].includes(item.order),
      );
      setData(updatedSortedData);
    }
  }, [newData]);

  const onChooseDropdown = (item: any) => {
    const index = currentDropdown.indexOf(item.item.order);
    if (index !== -1) {
      setCurrentDropdown(
        currentDropdown.filter((order: number) => order !== item.item.order),
      );
    } else {
      setCurrentDropdown([...currentDropdown, item.item.order]);
    }
  };

  const renderTitle = (value: any) => {
    switch (value) {
      case 1:
        return (
          <TextCM style={styles.txtItem}>
            {t('eContract.GS.DocumentCreationSuccessful')}
          </TextCM>
        );
      case 1.5:
        return (
          <TextCM style={styles.txtItem}>{t('eContract.GS.EndOfSigningStream')}</TextCM>
        );
      case 2:
        return (
          <TextCM style={styles.txtItem}>{t('eContract.GS.DocumentManipulation')}</TextCM>
        );
      case 3:
        return <TextCM style={styles.txtItem}>{t('eContract.GS.Consider')}</TextCM>;
      case 4:
        return <TextCM style={styles.txtItem}>{t('eContract.DC.TxtUserSigner')}</TextCM>;
      case 5:
        return <TextCM style={styles.txtItem}>{t('eContract.GS.Document')}</TextCM>;
      case 5.5:
        return <TextCM style={styles.txtItem}>{t('eContract.GS.Coordinator')}</TextCM>;
      case 6:
        return <TextCM style={styles.txtItem}>{t('eContract.GS.Replace')}</TextCM>;
      case 7:
        return <TextCM style={styles.txtItem}>{t('eContract.GS.Authorization')}</TextCM>;
      case 8:
        return <TextCM style={styles.txtItem}>{t('eContract.GS.Forward')}</TextCM>;
      case 9:
        return <TextCM style={styles.txtItem}>{t('eContract.GS.EndOfDocument')}</TextCM>;
      case 10:
        return <TextCM style={styles.txtItem}>{t('eContract.GS.Success')}</TextCM>;
      case 11:
        return <TextCM style={styles.txtItem}>{t('eContract.DC.TxtCancel')}</TextCM>;
      case 12:
        return <TextCM style={styles.txtItem}>{t('eContract.NT.TxtRejected')}</TextCM>;
      case 13:
        return <TextCM style={styles.txtItem}>{t('eContract.NT.TxtOverdue')}</TextCM>;
      case 14:
        return <TextCM style={styles.txtItem}>{t('eContract.GS.PromptToSign')}</TextCM>;
      default:
        break;
    }
  };
  const onPressMainItem = (item: number) => {
    let updatedMainCurrent = [...mainCurrent];

    const index = updatedMainCurrent.indexOf(item);
    if (index !== -1) {
      updatedMainCurrent.splice(index, 1);
      if (item === 2) {
        updatedMainCurrent = updatedMainCurrent.filter(
          (order: number) => ![2, 3, 4, 5, 5.5].includes(order),
        );
      } else if (item === 3 || item === 4 || item === 5 || item === 5.5) {
        updatedMainCurrent = updatedMainCurrent.filter(
          (order: number) => ![2].includes(order),
        );
      }
      if (item === 9) {
        updatedMainCurrent = updatedMainCurrent.filter(
          (order: number) => ![10, 11, 12, 13].includes(order),
        );
      } else if (item === 10 || item === 11 || item === 12 || item === 13) {
        updatedMainCurrent = updatedMainCurrent.filter(
          (order: number) => ![9].includes(order),
        );
      }
    } else {
      updatedMainCurrent.push(item);
      if (
        updatedMainCurrent.includes(3) &&
        updatedMainCurrent.includes(4) &&
        updatedMainCurrent.includes(5) &&
        updatedMainCurrent.includes(5.5) &&
        !updatedMainCurrent.includes(2)
      ) {
        updatedMainCurrent.push(2);
      }
      if (
        updatedMainCurrent.includes(10) &&
        updatedMainCurrent.includes(11) &&
        updatedMainCurrent.includes(12) &&
        updatedMainCurrent.includes(13) &&
        !updatedMainCurrent.includes(9)
      ) {
        updatedMainCurrent.push(9);
      }
      if (item === 2) {
        if (!updatedMainCurrent.includes(3)) updatedMainCurrent.push(3);
        if (!updatedMainCurrent.includes(4)) updatedMainCurrent.push(4);
        if (!updatedMainCurrent.includes(5)) updatedMainCurrent.push(5);
        if (!updatedMainCurrent.includes(5.5)) updatedMainCurrent.push(5.5);
      }
      if (item === 9) {
        if (!updatedMainCurrent.includes(10)) updatedMainCurrent.push(10);
        if (!updatedMainCurrent.includes(11)) updatedMainCurrent.push(11);
        if (!updatedMainCurrent.includes(12)) updatedMainCurrent.push(12);
        if (!updatedMainCurrent.includes(13)) updatedMainCurrent.push(13);
      }
    }

    setMainCurrent(updatedMainCurrent);
  };

  const handleOnsubmit = () => {
    for (let key in newData) {
      if (mainCurrent.includes(newData[key].order)) {
        newData[key].value = true;
      } else {
        newData[key].value = false;
      }
    }
    dataSubmit.attrs = newData;
    onSubmit(dataSubmit);
    onClose();
  };

  const _renderItem = (item: any) => {
    const isSelected = currentDropdown.includes(item.item.order);
    const isSelectedMain = mainCurrent.includes(item.item.order);
    return (
      <TouchableOpacity
        onPress={() => onPressMainItem(item.item.order)}
        key={item.item.order}
        style={styles.ctnCheckbox}>
        <ViewCM style={styles.ctnIcon}>
          <TouchableOpacity
            onPress={() => onPressMainItem(item.item.order)}
            style={styles.ctnCheckbox}>
            <ViewCM style={styles.ctnIcon}>
              {isSelectedMain ? (
                <IcCheckboxSelect width={SizeDP(24)} height={SizeDP(24)} />
              ) : (
                <IcCheckbox width={SizeDP(24)} height={SizeDP(24)} />
              )}
            </ViewCM>
            {item?.item?.children && (
              <TouchableOpacity
                onPress={() => onChooseDropdown(item)}
                style={[
                  styles.ctnDropdown,
                  {
                    transform: [
                      {
                        rotate: isSelected ? '90deg' : '0deg',
                      },
                    ],
                  },
                ]}>
                <IconDropdownUtility width={SizeDP(24)} height={SizeDP(24)} />
              </TouchableOpacity>
            )}
            {renderTitle(item.item.order)}
          </TouchableOpacity>
          {item?.item?.children && isSelected && (
            <ViewCM style={{marginLeft: SizeDP(32)}}>
              {item?.item?.children?.map((item: any) => {
                const isSelectedSubItem = mainCurrent.includes(item.order);
                return (
                  <TouchableOpacity
                    onPress={() => onPressMainItem(item.order)}
                    key={item.order}
                    style={styles.ctnCheckbox}>
                    <ViewCM style={styles.ctnIcon}>
                      {isSelectedSubItem ? (
                        <IcCheckboxSelect
                          width={SizeDP(24)}
                          height={SizeDP(24)}
                        />
                      ) : (
                        <IcCheckbox width={SizeDP(24)} height={SizeDP(24)} />
                      )}
                    </ViewCM>
                    {renderTitle(item.order)}
                  </TouchableOpacity>
                );
              })}
            </ViewCM>
          )}
        </ViewCM>
      </TouchableOpacity>
    );
  };
  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <ViewCM style={styles.ctnContainer}>
        <ViewCM style={styles.ctnTop} onTouchEnd={onClose} />
        <ViewCM
          style={[
            styles.ctnContent,
            {
              paddingBottom: insets.bottom,
              height: (Dimensions.get('window').height / 4) * 3,
            },
          ]}>
          <ViewCM style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={SizeDP(14)} height={SizeDP(16)} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>{t('eContract.GS.config')}</TextCM>
            <ViewCM />
          </ViewCM>
          <ScrollView>
            <ViewCM style={styles.viewBody}>
              <TextCM style={styles.txtLabel}>
                {t('eContract.GS.EmailNotifications')}
              </TextCM>
              <FlatList
                scrollEnabled={false}
                data={dataCustom}
                renderItem={_renderItem}
                showsVerticalScrollIndicator={false}
              />
              <ButtonCM label={t('eContract.CM.TxtSave')} onPress={handleOnsubmit} />
            </ViewCM>
          </ScrollView>
        </ViewCM>
      </ViewCM>
    </Modal>
  );
};

export default ModalConfigurationEmail;
