import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {TouchableOpacity, View} from 'react-native';
import styles from './styles';
import {getDataType} from './helper';
import GroupRadio, {
  GroupData,
} from '../../../../../../../components/GroupRadio';
import TextCM from '../../../../../../../components/Text';
import {IconBlackDown} from '../../../../../../../assets/images';
import BottomSheetCM from '../../../../../../../components/BottomSheet';
import {useDocumentStore} from '../../../../../../../navigation/SideMenu/store/app-store';
import ButtonCM from '../../../../../../../components/Button';

type Props = {
  value: GroupData;
  onPicType: (value: GroupData | null) => void;
  onDismissKeyboard?: () => void;
};

const PicTypeView = ({value, onPicType, onDismissKeyboard}: Props) => {
  const {t} = useTranslation();

  const [isVisible, setIsVisible] = useState<boolean>(false);

  const togglePicType = () => {
    if (onDismissKeyboard) {
      onDismissKeyboard();
    }
    setIsVisible(!isVisible);
  };

  return (
    <>
      <TouchableOpacity style={styles.btnPicType} onPress={togglePicType}>
        {value ? (
          <View>
            <TextCM style={styles.txtLabel}>{t('eContract.DC.modal.TxtPicDate')}</TextCM>
            <TextCM style={styles.txtType}>{value?.label}</TextCM>
          </View>
        ) : (
          <TextCM style={styles.txtNoType}>{t('eContract.DC.modal.TxtPicDate')}</TextCM>
        )}
        <IconBlackDown width={16} height={16} />
      </TouchableOpacity>
      <BottomSheetCM
        renderContent={
          <ContentPicTypeView
            value={value}
            onPicType={onPicType}
            togglePicType={togglePicType}
          />
        }
        title={t('eContract.DC.modal.TxtPicDate')}
        onClose={togglePicType}
        isVisible={isVisible}
      />
    </>
  );
};

type ContentPicTypeViewProps = {
  value: GroupData;
  onPicType: (value: GroupData | null) => void;
  togglePicType: () => void;
};

const ContentPicTypeView = ({
  value,
  onPicType,
  togglePicType,
}: ContentPicTypeViewProps) => {
  const {t} = useTranslation();

  const currentFocused = useDocumentStore(state => state.currentFocused);
  const [type, setType] = useState<GroupData | null>(value);

  const onPressData = (value: GroupData) => {
    setType(value);
  };

  const onPressConfirm = () => {
    togglePicType();
    onPicType(type);
  };

  return (
    <View style={styles.viewPicType}>
      <TextCM style={styles.txtTitlePicType}>
        {t('eContract.DC.modal.TxtPicTypeDate')}
      </TextCM>
      <GroupRadio
        data={getDataType(currentFocused) as GroupData[]}
        onPressData={onPressData}
        currentValue={type as GroupData}
        containerStyle={styles.viewGroupRadio}
      />
      <ButtonCM label={t('eContract.CM.BtnConfirm')} onPress={onPressConfirm} />
    </View>
  );
};

export default PicTypeView;
