import React, {FC} from 'react';
import {FlatList, Modal, TouchableOpacity, View} from 'react-native';
import styles from './styles';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import {useTranslation} from 'react-i18next';
import {isEmpty} from 'lodash';
import {IDocumentError} from '../../../../model/interface/envelope.interface';
import TextCM from '../../../../components/Text';
import {
  IcBlackLeftArrow,
  IconDeleteDocumentError,
  IconRetryDocument,
} from '../../../../assets/images';
import ButtonCM from '../../../../components/Button';
import Toast from 'react-native-toast-message';
import {useDocumentServices} from '../../../../hook/apiHook/useApi';

type Props = {
  isVisible: boolean;
  data: IDocumentError[];
  onClose: () => void;
  handleCallBack: () => void;
};

enum TypeStatus {
  Rejected = 'rejected',
  Failure = 'failure',
  Waiting = 'waiting',
}

const ModalListDocumentError: FC<Props> = ({
  isVisible,
  onClose,
  data,
  handleCallBack,
}) => {
  const {t} = useTranslation();
  const insets = useSafeAreaInsets();

  const DocumentServices = useDocumentServices();

  const onRetry = (item: any) => {
    const body = item;
    body.status = TypeStatus.Waiting;
    DocumentServices.retryDocumentError([body]).then(data => {
      if (!isEmpty(data)) {
        onClose();
        handleCallBack();
        Toast.show({
          type: 'success',
          text1: t('eContract.DC.TxtRetrySuccess'),
        });
      }
    });
  };
  const onCancel = (item: any) => {
    const body = item;
    body.status = TypeStatus.Rejected;
    DocumentServices.retryDocumentError([body]).then(data => {
      if (!isEmpty(data)) {
        onClose();
        handleCallBack();
        Toast.show({
          type: 'success',
          text1: t('eContract.DC.TxtCancelSuccess'),
        });
      }
    });
  };

  const onCancelAll = () => {
    const body = data;
    body.forEach((obj: any) => {
      obj.status = TypeStatus.Rejected;
    });
    DocumentServices.retryDocumentError(body).then(data => {
      if (!isEmpty(data)) {
        onClose();
        handleCallBack();
        Toast.show({
          type: 'success',
          text1: t('eContract.DC.TxtCancelSuccess'),
        });
      }
    });
  };

  const onRetryAll = () => {
    const body = data;
    body.forEach((obj: any) => {
      obj.status = TypeStatus.Rejected;
    });
    DocumentServices.retryDocumentError(body).then(data => {
      if (!isEmpty(data)) {
        onClose();
        handleCallBack();
        Toast.show({
          type: 'success',
          text1: t('eContract.DC.TxtRetrySuccess'),
        });
      }
    });
  };

  const renderStatus = (item: any) => {
    switch (item.status) {
      case TypeStatus.Rejected:
        return (
          <View style={styles.ctnViewStatus}>
            <View style={styles.viewCircleStatus} />
            <TextCM style={styles.txtRejected}>Rejected</TextCM>
          </View>
        );
      case TypeStatus.Failure:
        return (
          <View style={styles.ctnStatusFailure}>
            <View style={styles.ctnViewStatus}>
              <View style={[styles.viewCircleStatus, styles.BgrColorE18308]} />
              <TextCM style={[styles.txtRejected, styles.ColorE18308]}>
                Failure
              </TextCM>
            </View>
            <View style={styles.ctnAction}>
              <TouchableOpacity onPress={() => onCancel(item)}>
                <IconDeleteDocumentError width={32} height={32} />
              </TouchableOpacity>
              <TouchableOpacity onPress={() => onRetry(item)}>
                <IconRetryDocument width={32} height={32} />
              </TouchableOpacity>
            </View>
          </View>
        );
      default:
        return (
          <View style={styles.ctnViewStatus}>
            <View style={styles.viewCircleStatus} />
            <TextCM style={styles.txtRejected}>Rejected</TextCM>
          </View>
        );
    }
  };

  const renderItem = ({item, index}: {item: IDocumentError; index: number}) => {
    const objectName = item.datas.find((obj: any) => obj.id === 'envName');
    const objectIdDocument = item.datas.find((obj: any) => obj.id === 'envNo');
    return (
      <View style={styles.ctnMainItem} key={index}>
        <TextCM style={styles.txtLabelItem}>{objectName.value}</TextCM>
        {!isEmpty(objectIdDocument.value) && (
          <View style={styles.ctnViewItem}>
            <TextCM style={styles.txtTitleItem}>
              {t('eContract.DC.TxtIdContracts')}
            </TextCM>
            <TextCM style={styles.txtValueItem}>
              {objectIdDocument.value}
            </TextCM>
          </View>
        )}
        <View style={styles.line} />
        {renderStatus(item)}
      </View>
    );
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <View style={styles.ctnContainer}>
        <View style={styles.ctnTop} onTouchEnd={onClose} />
        <View style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
          <View style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={14} height={16} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>
              {t('eContract.DC.TxtListDocumentCancel')}
            </TextCM>
            <View />
          </View>
          <View style={styles.ctnBody}>
            <View style={{flex: 1}}>
              <FlatList
                showsVerticalScrollIndicator={false}
                keyExtractor={item => item.id.toString()}
                data={data}
                renderItem={renderItem}
              />
            </View>
            <View style={styles.ctnGroupButton}>
              <ButtonCM
                style={styles.customButtonContainerCancel}
                styleLabel={styles.customLabelButtonCancel}
                onPress={onCancelAll}
                label={t('eContract.DC.TxtCancelAll')}
              />
              <ButtonCM
                style={styles.customButtonContainerRetry}
                styleLabel={styles.customLabelButtonRetry}
                onPress={onRetryAll}
                label={t('eContract.DC.TxtRetryAll')}
              />
            </View>
          </View>
        </View>
      </View>
    </Modal>
  );
};

export default ModalListDocumentError;
