import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {TouchableOpacity} from 'react-native';
import styles from './styles';
import ModalUpdateOrganization from '../ModalUpdateOrganization';
import { useAppSelector } from '../../../../hook/useRedux';
import TextCM from '../../../../components/Text';
import { View as ViewCM } from 'react-native';
import { IconBlueOrganization, IconOrangePen } from '../../../../assets/images';
import { SizeDP } from '../../../../constants/Size';
import { String } from '../../../../constants';

const OrganizationInfo = () => {
  const {t} = useTranslation();

  const user = useAppSelector(state => state.account.dataAccount);
  const [isVisibleEdit, setIsVisibleEditEdit] = useState(false);

  const {organization} = user;

  const toggleModalEdit = () => {
    setIsVisibleEditEdit(!isVisibleEdit);
  };

  const DATA_INFO = [
    {
      label: t('eContract.AI.TxtCompanyName'),
      value: organization?.name,
    },
    {
      label: t('eContract.AI.TxtShortName'),
      value: organization?.acName,
    },
    {
      label: t('eContract.AI.TxtTaxCode'),
      value: organization?.taxCode,
    },
    {
      label: t('eContract.AI.TxtOrganizationCode'),
      value: organization?.orgCode,
    },
  ];

  const renderItem = (item: any) => {
    return (
      <ViewCM style={styles.viewItem} key={item.label}>
        <TextCM style={styles.txtLabelItem}>{item.label}</TextCM>
        <ViewCM style={styles.viewTxtItem}>
          <TextCM style={styles.txtItem}>{item.value || '---'}</TextCM>
        </ViewCM>
      </ViewCM>
    );
  };

  return (
    <ViewCM style={styles.container}>
      <ViewCM style={styles.header}>
        <IconBlueOrganization width={SizeDP(18)} height={SizeDP(18)} />
        <TextCM style={styles.txtHeader}>{t('eContract.AI.TxtOrganizationInfo')}</TextCM>
        {user.authorities?.includes(String.ROLE.ROLE_ORG_ADMIN) && (
          <TouchableOpacity onPress={toggleModalEdit}>
            <IconOrangePen width={SizeDP(18)} height={SizeDP(18)} />
          </TouchableOpacity>
        )}
      </ViewCM>
      <ViewCM style={styles.body}>{DATA_INFO.map(renderItem)}</ViewCM>
      <ModalUpdateOrganization
        onClose={toggleModalEdit}
        isVisible={isVisibleEdit}
      />
    </ViewCM>
  );
};

export default OrganizationInfo;
