import {
  useFocusEffect,
  useNavigation,
  useRoute,
} from '@react-navigation/native';
import {debounce, isEmpty} from 'lodash';
import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {FlatList, RefreshControl, TouchableOpacity, View} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import InputSearch from './components/InputSearch';
import ModalFilter from './components/ModalFilter';
import ModalInfoCA from './components/ModalInfoCA';
import ModalSignDozen from './components/ModalSignDozen';
import NotificationItem from './components/NotificationItem';
import styles from './styles';
import {useIsFocused} from '@react-navigation/native';
import {INotification} from '../../../model/interface/notification.interface';
import {useCreateNotiServices} from '../../../hook/apiHook/useApi';
import {NavigationName} from '../../../constants';
import Toast from 'react-native-toast-message';
import HeaderCM from '../../../components/Header/HeaderCM';
import TextCM from '../../../components/Text';
import CheckboxCM from '../../../components/Checkbox';
import ButtonCM from '../../../components/Button';
import useStoreNoti from '../store/store';

export enum NotificationType {
  Process = 'Process',
  Status = 'Status',
}

const NotificationListScreen = () => {
  const {t} = useTranslation();
  const route = useRoute<any>();
  const isFocused = useIsFocused();

  const navigation = useNavigation<any>();
  const [searchText, setSearchText] = useState<string>('');
  const [debouncedSearchText, setDebouncedSearchText] = useState('');
  const [data, setData] = useState<INotification[]>([]);
  const [totalPage, setTotalPage] = useState(1);
  const [page, setPage] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isShowFilter, setIsShowFilter] = useState(false);
  const [filterData, setFilterData] = useState<any>({});
  const [isPicAll, setIsPicAll] = useState(false);

  const [modalSignDozen, setModalSignDozen] = useState(false);

  const [modalInfoCA, setModalInfoCA] = useState(false);

  const isSignDozen = route.params?.isSignDozen || false;
  const NotificationServices = useCreateNotiServices();
  const {
    reLoadDataNotification,
    listNotifications,
    currentSignDozens,
    setListNotifications,
    setCurrentSignDozens,
    setReloadDataNotification,
  } = useStoreNoti();

  const debouncedSearch = debounce((text: string) => {
    setDebouncedSearchText(text);
  }, 300);

  useFocusEffect(
    React.useCallback(() => {
      getData(0, debouncedSearchText, filterData);
      resetCurrentSignDozens();
    }, [debouncedSearchText, filterData, reLoadDataNotification]),
  );

  const getData = async (
    page = 0,
    keyWord = '',
    filterData?: {sort: any; search: any; sort3?: string} | undefined,
  ) => {
    const params = {
      page,
      size: 10,
      search: JSON.stringify({
        terms: filterData?.search?.terms || {
          status: 'processing',
          envelopeStatus: 'processing',
        },
        keyWord,
        field: filterData?.search?.field,
        from: filterData?.search?.from,
        to: filterData?.search?.to,
        id: null,
      }),
    };

    const sort = {
      sort: 'refId,desc',
      sort2: filterData?.sort || 'createdDate,desc',
      sort3: filterData?.sort3,
    };

    const dataResp = await NotificationServices.getDataNotification(
      params,
      sort,
    );
    if (page) {
      setListNotifications([...data, ...dataResp.data]);
      setData(prev => [...prev, ...dataResp.data]);
    } else {
      setPage(0);
      setListNotifications([...dataResp.data]);
      setData(dataResp.data);
    }

    setTotalPage(dataResp.totalPage);
    setIsRefreshing(false);
  };

  useEffect(() => {
    debouncedSearch(searchText);
    return () => {
      debouncedSearch.cancel();
    };
  }, [searchText]);

  const toggleShowFilter = () => {
    setIsShowFilter(!isShowFilter);
  };

  const onEndReached = async () => {
    if (totalPage > 1 && page + 1 < totalPage && isFocused) {
      getData(page + 1, debouncedSearchText, filterData);
      setPage(page + 1);
      setIsPicAll(false);
    }
  };

  const onRefresh = async () => {
    setIsRefreshing(true);
    resetCurrentSignDozens();
    getData(0, debouncedSearchText, filterData);
  };

  const resetCurrentSignDozens = () => {
    setIsPicAll(false);
    setCurrentSignDozens([]);
  };

  const renderItem = ({item}: {item: INotification}) => {
    return <NotificationItem data={item} isSignDozen={isSignDozen} />;
  };

  const onFilter = (data: any) => {
    setFilterData(data);
  };

  const onPressSignDozen = () => {
    navigation.navigate(NavigationName.SignDozenScreen, {
      isSignDozen: true,
    });
  };

  const onPicAllSignDozen = () => {
    setIsPicAll(!isPicAll);
    setCurrentSignDozens(
      !isPicAll ? data.filter(i => checkShowSignDozen(i)) : [],
    );
  };

  const toggleModalSignDozen = () => {
    setModalSignDozen(!modalSignDozen);
  };

  const toggleModalInfoCA = () => {
    setModalInfoCA(!modalInfoCA);
  };

  const onSignDozen = () => {
    const listInputSignType = currentSignDozens.map(i => i.inputSignType);

    if (listInputSignType.every(i => i === '0')) {
      onSignDozenOther();
    } else if (listInputSignType.every(i => i === '2' || i === '0')) {
      toggleModalInfoCA();
    } else {
      toggleModalSignDozen();
    }
  };

  const onSignDozenOther = async () => {
    const ls = currentSignDozens.filter(i => i.inputSignType === '0');
    const body = ls.map(item => ({
      selector: 'sign_lot',
      refId: 'sign_lot',
      attrs: {},
      payload: JSON.stringify({
        notifyId: item.id,
        recipientRole: item.role,
        envelopeId: item.recipients[0]?.attrs.header.envelopeId,
        recipientId: item.recipients[0]?.id,
        recipientEmail: item.recipients[0]?.email,
        passWord: item.recipients[0]?.password,
        passCodeUser: null,
        passCodePassWord: null,
        imageSignature: null,
      }),
    }));
    try {
      await NotificationServices.putProcessing(
        currentSignDozens.map(item => item.id),
      );
      await NotificationServices.signDozen(body);
      setCurrentSignDozens([]);
      setReloadDataNotification(!reLoadDataNotification);
      Toast.show({
        type: 'success',
        text1: t('eContract.NT.message.successSignDozen'),
      });
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('eContract.CM.TxtSystemError'),
      });
    }
  };

  const checkShowSignDozen = (data: INotification) => {
    let rs = false;
    if (
      data.inputSign &&
      (data.status.startsWith('need-') || data.status.startsWith('processing'))
    ) {
      const recipient = data.recipients[0];
      if (!isEmpty(recipient) && recipient.status === 'processing') {
        rs = true;
      }
    }
    return rs;
  };

  const onNextStep = () => {
    setModalSignDozen(false);
    setTimeout(() => {
      setModalInfoCA(true);
    }, 500);
  };

  const getTotalSignDozen = () => {
    const total = currentSignDozens.filter(i => checkShowSignDozen(i)).length;
    if (!total) return '';
    return `(${total})`;
  };

  const getTotalAllSignDozen = () => {
    const total = data.filter(i => checkShowSignDozen(i)).length;
    if (!total) return '0';
    return total;
  };

  return (
    <SafeAreaView style={styles.ctnMain} edges={isSignDozen ? ['bottom'] : []}>
      <HeaderCM
        title={
          !isSignDozen ? t('eContract.NT.TxtNotification') : t('eContract.NT.TxtActionSignDozen')
        }
      />
      <View style={styles.body}>
        <InputSearch
          searchText={searchText}
          setSearchText={setSearchText}
          onPressFilter={toggleShowFilter}
        />

        {!isSignDozen ? (
          <TouchableOpacity onPress={onPressSignDozen}>
            <TextCM style={styles.txtSignDozen}>
              {t('eContract.NT.TxtActionSignDozen')}
            </TextCM>
          </TouchableOpacity>
        ) : (
          <View style={styles.viewSelectAll}>
            <TouchableOpacity style={styles.btnSelectAll}>
              <CheckboxCM
                checked={isPicAll}
                onChange={onPicAllSignDozen}
                label={t('eContract.NT.TxtPicAll')}
              />
              <TextCM style={styles.txtTotalSign}>{getTotalSignDozen()}</TextCM>
            </TouchableOpacity>
            <TextCM style={styles.txtTotalAllSign}>
              {t('eContract.NT.TxtNumberItemSign', {
                total: getTotalAllSignDozen(),
              })}
            </TextCM>
          </View>
        )}
        <FlatList
          data={listNotifications}
          keyExtractor={item => item.id}
          contentContainerStyle={styles.ctnFlatList}
          renderItem={renderItem}
          onEndReached={onEndReached}
          onEndReachedThreshold={0.5}
          showsVerticalScrollIndicator={false}
          refreshControl={
            <RefreshControl refreshing={isRefreshing} onRefresh={onRefresh} />
          }
          ListEmptyComponent={<Nodata />}
        />
      </View>
      {isSignDozen && (
        <View style={styles.viewSignDozen}>
          <ButtonCM
            onPress={onSignDozen}
            label={t('eContract.NT.TxtActionSignDozen')}
            disabled={isEmpty(currentSignDozens)}
          />
        </View>
      )}
      <ModalFilter
        onFilter={onFilter}
        isShowFilter={isShowFilter}
        toggleShowFilter={toggleShowFilter}
        filterData={filterData}
      />

      {modalSignDozen && (
        <ModalSignDozen
          isVisible={modalSignDozen}
          onClose={toggleModalSignDozen}
          onNextStep={onNextStep}
        />
      )}

      {modalInfoCA && (
        <ModalInfoCA isVisible={modalInfoCA} onClose={toggleModalInfoCA} />
      )}
    </SafeAreaView>
  );
};

export default NotificationListScreen;

const Nodata = () => {
  const {t} = useTranslation();
  return <TextCM style={styles.txtNoData}>{t('eContract.NT.TxtNoData')}</TextCM>;
};
