import {yupResolver} from '@hookform/resolvers/yup';
import React, {useState} from 'react';
import {
  Controller,
  FormProvider,
  useForm,
  useFormContext,
} from 'react-hook-form';
import {useTranslation} from 'react-i18next';
import {
  KeyboardAvoidingView,
  Modal,
  TouchableOpacity,
  View,
} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import * as yup from 'yup';
import styles from './styles';
import {IDocument} from '../../../../../model/interface/envelope.interface';
import {IcBlackLeftArrow} from '../../../../../assets/images';
import TextCM from '../../../../../components/Text';
import ButtonCM from '../../../../../components/Button';
import ModalConfirm from '../../../../../components/ModalConfirm';
import Toast from 'react-native-toast-message';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';
import TextFieldCM from '../../../../../components/TextField';

type ModalDisableDocumentProp = {
  onClose: () => void;
  isVisible: boolean;
  data: IDocument;
  fetching: () => void;
};

const schema = yup.object().shape({
  text: yup.string(),
});

const ModalDisableDocument = ({
  data,
  onClose,
  isVisible,
  fetching,
}: ModalDisableDocumentProp) => {
  const {t} = useTranslation();
  const insets = useSafeAreaInsets();
  const [showModalConfirm, setShowModalConfirm] = useState(false);
  const methods = useForm({
    mode: 'onBlur',
    resolver: yupResolver(schema),
    defaultValues: {
      text: '',
    },
  });

  const DocumentServices = useDocumentServices();

  const onSubmit = async () => {
    try {
      const res = await DocumentServices.disableEnvelope(
        data?.id,
        methods.getValues('text') ?? '',
      );
      Toast.show({
        type: 'success',
        text1: t('eContract.DC.DisableDocument.disableSuccess'),
      });
    } catch (error) {
    } finally {
      toggleModalConfirm();
      fetching();
      onClose();
    }
  };

  const toggleModalConfirm = () => {
    setShowModalConfirm(!showModalConfirm);
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <KeyboardAvoidingView
        style={{flex: 1}}
        behavior={'padding'}
        keyboardVerticalOffset={-insets.bottom}>
        <View style={styles.ctnContainer}>
          <View style={styles.ctnTop} onTouchEnd={onClose} />
          <View style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
            <View style={styles.viewHeader}>
              <TouchableOpacity onPress={onClose}>
                <IcBlackLeftArrow width={14} height={16} />
              </TouchableOpacity>
              <TextCM style={styles.txtTitle}>
                {t('eContract.DC.DisableDocument.title')}
              </TextCM>
              <View />
            </View>
            <View style={styles.viewBody}>
              <FormProvider {...methods}>
                <YupTextField
                  controlName="text"
                  label={t('eContract.DC.DisableDocument.content')}
                />
                <ButtonCM
                  disabled={!methods.formState.isValid}
                  label={t('eContract.CM.BtnConfirm')}
                  onPress={toggleModalConfirm}
                />
              </FormProvider>
            </View>
          </View>
        </View>
      </KeyboardAvoidingView>
      <ModalConfirm
        onClose={toggleModalConfirm}
        onConfirm={onSubmit}
        isVisible={showModalConfirm}
        title={t('eContract.DC.DisableDocument.title')}
      />
    </Modal>
  );
};

type Props = {
  controlName: string;
  label: string;
  maxLength?: number;
  onPressIconRight?: () => void;
  viewIconRight?: React.ReactNode;
};

const YupTextField = ({
  controlName,
  label,
  maxLength,
  onPressIconRight,
  viewIconRight,
}: Props) => {
  const {
    control,
    formState: {errors},
  } = useFormContext();

  return (
    <View>
      <Controller
        control={control}
        name={controlName}
        render={({field: {onChange, onBlur, value}}) => {
          return (
            <TextFieldCM
              label={label}
              placeholder={label}
              value={value}
              onBlur={onBlur}
              onChangeText={onChange}
              onIconPress={onPressIconRight}
              maxLength={maxLength}
              errorMessage={errors[controlName]?.message as string}
              viewIconRight={viewIconRight}
            />
          );
        }}
      />
    </View>
  );
};

export default ModalDisableDocument;
