import React from 'react';
import {useTranslation} from 'react-i18next';
import {getDataSortDate} from './helper';
import styles from './styles';
import GroupRadio, {
  GroupData,
} from '../../../../../../../components/GroupRadio';
import {useDocumentStore} from '../../../../../../../navigation/SideMenu/store/app-store';
import {View} from 'react-native';
import TextCM from '../../../../../../../components/Text';
import {ItemType} from '../../../../../../../navigation/SideMenu/components/CustomDrawerContent/helper';

type Props = {
  data: GroupData | undefined;
  onChangeSortDate: (item: any) => void;
};

const SortDateView = ({onChangeSortDate, data}: Props) => {
  const {t} = useTranslation();

  const currentFocused = useDocumentStore(state => state.currentFocused);

  const onChoiceSortDate = (item: any) => {
    onChangeSortDate(item);
  };

  return (
    <View style={styles.container}>
      <TextCM style={styles.txtTitle}>{t('eContract.DC.modal.TxtSortByDate')}</TextCM>
      <GroupRadio
        numColumns={currentFocused == ItemType.Draft ? 1 : 2}
        currentValue={data}
        data={getDataSortDate(currentFocused) as GroupData[]}
        onPressData={onChoiceSortDate}
      />
    </View>
  );
};

export default SortDateView;
