export const getTitleProcessing = (status: RoleNotification) => {
  switch (status) {
    case RoleNotification.signer:
      return 'eContract.NT.TxtSignature';
    case RoleNotification.coordinator:
      return 'eContract.NT.TxtCoordination';
    case RoleNotification.reviewer:
      return 'eContract.NT.TxtReview';
    case RoleNotification.stamper:
      return 'eContract.NT.TxtHide';
    default:
      return '';
  }
};

export const mapStatus = (data: INotification) => {
  var status = data.status;
  if (data.envelopeStatus !== EnvelopeStatus.processing) {
    status = data.envelopeStatus;
  }
  return status;
};

export const getTaskPriorityLabel = (refId: string) => {
  const priority = +refId;
  switch (priority) {
    case 6:
      return {
        value: 'NT.priority.high',
        color: '#F04438',
        bgColor: '#FEECEB',
        icon: <IconRedPriorityNoti width={12} height={16} />,
      };
    case 5:
      return {
        value: 'NT.priority.medium',
        color: '#077EDA',
        bgColor: '#E6F2FB',
        icon: <IconBluePriorityNoti width={12} height={16} />,
      };
    default:
      return {
        value: 'NT.priority.medium',
        color: '#24A148',
        bgColor: '#E9F6ED',
        icon: <IconGreenPriorityNoti width={12} height={16} />,
      };
  }
};

export const formatText = (input: string): string => {
  return input.charAt(0).toUpperCase() + input.slice(1).toLowerCase();
};
