import {useTranslation} from 'react-i18next';
import {SafeAreaView} from 'react-native-safe-area-context';
import styles from './styles';
import {ScrollView, TouchableOpacity, View} from 'react-native';
import {useEffect, useState} from 'react';
import {useRoute} from '@react-navigation/native';
import {isUndefined} from 'lodash';
import {listStatus} from '../notification-list/components/NotificationItem/helper';
import TextCM from '../../../components/Text';
import {StatusNotification} from '../../../model/interface/notification.interface';
import ButtonCM from '../../../components/Button';
import React from 'react';
import {DateUtils} from '../../../utils';
import HeaderCM from '../../../components/Header/HeaderCM';
import {
  IconBlueListSigned,
  IconCreateDate,
  IconGreyDocumentUser,
  IconGreyStatus,
} from '../../../assets/images';
import BottomSheetCM from '../../../components/BottomSheet';
import {Font} from '../../../constants';
import {useCreateNotiServices} from '../../../hook/apiHook/useApi';
import {
  getListRecipient,
  IExtendedRecipients,
} from '../../document/document-history/helper';
import {IParties} from '../../../model/interface/envelope.interface';
import {
  convertHistoryStatus,
  mappingColorHistoryStatus,
  mappingRecipientToText,
} from '../../document/helper';
import ModadlHistoryRecipient from '../../document/document-history/components/ModalHistoryRecipients';
import ModalIntuitiveSigning from '../../document/document-history/components/ModalIntuitiveSigning';

const NotificationHistory = () => {
  const {t} = useTranslation();
  const route = useRoute<any>();
  const {envId} = route?.params;
  const [dataNotifi, setDataNotifi] = useState<any>();
  const [recipientsHistory, setRecipientsHistory] = useState<any>();
  const [isVisible, setIsVisible] = useState<boolean>(false);
  const [modalSigningProcess, setModalSigningProcess] = useState(false);
  const [isVisibleDetail, setIsVisibleDetail] = useState<boolean>(false);
  const [detailUser, setDetailUser] = useState<IExtendedRecipients>();

  const NotificationServices = useCreateNotiServices();

  useEffect(() => {
    (async () => {
      try {
        const dataResp = await NotificationServices.getNotificationHistoryById(
          envId,
        );
        setDataNotifi(dataResp.data[0]);
        setRecipientsHistory(
          dataResp.data[0]?.parties[0]?.recipients?.[0].recipientsHistory[0],
        );
      } catch (error) {}
    })();
  }, []);

  const toggleModalSigningProcess = () => {
    setModalSigningProcess(!modalSigningProcess);
  };

  const renderStatus = () => {
    let status: any;
    if (
      !isUndefined(recipientsHistory) &&
      (recipientsHistory?.action === 'delegate' ||
        recipientsHistory?.action === 'forward')
    ) {
      status = listStatus.find(item => item.type === recipientsHistory?.action);
    } else {
      status = listStatus.find(item => item.type === dataNotifi.status);
    }

    return (
      <View style={styles.ctnStatus}>
        <TextCM
          style={[
            styles.txtStatus,
            {
              color: status?.color,
            },
          ]}>
          • {t(status?.title)}
        </TextCM>
        {status.type === StatusNotification.voided && (
          <TouchableOpacity onPress={() => setIsVisible(true)}>
            <TextCM style={styles.textCm}>{`(${t('eContract.DC.reasonCancel')})`}</TextCM>
          </TouchableOpacity>
        )}
      </View>
    );
  };
  const renderContentVoiced = () => {
    return (
      <>
        <TextCM style={styles.txtTitleCancel}>{t('eContract.DC.reason')}</TextCM>
        <TextCM style={styles.textReason}>
          {dataNotifi?.requester?.reason}
        </TextCM>
        <ButtonCM
          label={t('eContract.CM.BtnClose')}
          onPress={() => setIsVisible(false)}
        />
      </>
    );
  };

  const onPressRecipient = (item: IExtendedRecipients) => {
    setDetailUser(item);
    setIsVisibleDetail(true);
  };

  const onCloseModalDetailUser = () => {
    setIsVisibleDetail(false);
    setDetailUser(undefined);
  };
  const renderItem = (value: IParties[]) => {
    const dataRender = getListRecipient(value);
    return (
      <View style={styles.viewListItem}>
        {dataRender.map((item, index) => {
          const historyStatus = convertHistoryStatus(item.status, item.role);
          return (
            <View key={index} style={styles.itemSigner}>
              <TouchableOpacity
                onPress={() => onPressRecipient(item)}
                style={styles.itemTopSigner}>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txtNameSigner}>
                    {item?.contact?.name}
                  </TextCM>
                  <TextCM
                    style={[
                      styles.txtValue,
                      {color: mappingColorHistoryStatus(historyStatus)},
                    ]}>{`• ${t(mappingRecipientToText(historyStatus))}`}</TextCM>
                </View>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txtLabelInfo}>{t('eContract.DC.company')}</TextCM>
                  <TextCM style={[styles.txtValue]}>
                    {item.partyName || '---'}
                  </TextCM>
                </View>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txtLabelInfo}>
                    {t('eContract.AI.TxtEmail')}
                  </TextCM>
                  <TextCM style={[styles.txtValue]}>
                    {item?.contact?.email}
                  </TextCM>
                </View>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txtLabelInfo}>
                    {t('eContract.AI.TxtPhone')}
                  </TextCM>
                  <TextCM style={[styles.txtValue]}>
                    {item?.contact.phone || '---'}
                  </TextCM>
                </View>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txtLabelInfo}>
                    {t('eContract.GS.history.operateDay')}
                  </TextCM>
                  <TextCM style={[styles.txtValue]}>
                    {DateUtils.convertDateToDDMMYYYYhhmm(item?.signDate) ||
                      '---'}
                  </TextCM>
                </View>
                {historyStatus === 'rejected-signing' && (
                  <View style={styles.rowInfo}>
                    <TextCM style={styles.txtLabelInfo}>
                      {t('eContract.DC.reason')}
                    </TextCM>
                    <TextCM
                      style={[
                        styles.txtValue,
                        {
                          fontFamily: Font.InterSemiBold600,
                          color: '#DA3E33',
                        },
                      ]}>
                      {item.reason || '---'}
                    </TextCM>
                  </View>
                )}
              </TouchableOpacity>
            </View>
          );
        })}
      </View>
    );
  };

  return (
    <SafeAreaView edges={['bottom']} style={styles.ctnMain}>
      <HeaderCM title={t('eContract.DC.TxtHistoryDocument')} />
      {!isUndefined(dataNotifi) && (
        <ScrollView>
          <View style={styles.contain}>
            <View style={styles.body}>
              <TextCM style={[styles.txtTitle]}>{dataNotifi?.name}</TextCM>
              <View style={styles.groupInfoDC}>
                <View style={styles.viewItem}>
                  <View style={styles.viewName}>
                    <IconCreateDate width={16} height={16} />
                    <TextCM style={styles.txtName}>
                      {t('eContract.DC.TxtCreateDate')}
                    </TextCM>
                  </View>
                  <TextCM style={styles.txtValue}>
                    {DateUtils.convertDateToDDMMYYYY(dataNotifi.createdDate)}
                  </TextCM>
                </View>
                <View style={styles.viewItem}>
                  <View style={styles.viewName}>
                    <IconGreyDocumentUser width={16} height={16} />
                    <TextCM style={styles.txtName}>
                      {t('eContract.DC.TxtUserCreate')}
                    </TextCM>
                  </View>
                  <TextCM style={styles.txtValue}>{dataNotifi?.owner}</TextCM>
                </View>
                <View style={styles.viewItem}>
                  <View style={styles.viewName}>
                    <IconGreyStatus width={16} height={16} />
                    <TextCM style={styles.txtName}>{t('eContract.DC.status')}</TextCM>
                  </View>
                  <View>
                    <View style={styles.reasonView}>{renderStatus()}</View>
                  </View>
                </View>
              </View>
            </View>
          </View>
          <View style={styles.sperateView} />
          <View style={styles.signedView}>
            <View style={styles.rowHeader}>
              <View style={styles.groupLeft}>
                <IconBlueListSigned width={16} height={16} />
                <TextCM style={styles.txtSigned}>{t('eContract.DC.listSign')}</TextCM>
              </View>
              <TouchableOpacity onPress={toggleModalSigningProcess}>
                <TextCM style={styles.txtProcesssing}>
                  {t('eContract.DC.intuitiveSigningProcess')}
                </TextCM>
              </TouchableOpacity>
            </View>
            {renderItem(dataNotifi?.parties)}
          </View>
        </ScrollView>
      )}

      <BottomSheetCM
        title={t('eContract.DC.reasonCancel')}
        onClose={() => setIsVisible(false)}
        isVisible={isVisible}
        renderContent={renderContentVoiced()}
      />

      {!isUndefined(detailUser) && (
        <ModadlHistoryRecipient
          isVisible={isVisibleDetail}
          onClose={onCloseModalDetailUser}
          recipientId={detailUser.id}
          documentId={envId}
        />
      )}

      {dataNotifi?.parties && (
        <ModalIntuitiveSigning
          onClose={toggleModalSigningProcess}
          isVisible={modalSigningProcess}
          data={dataNotifi}
        />
      )}
    </SafeAreaView>
  );
};

export default NotificationHistory;
